 recovery=p.evaluate('(id)=>__forecastProbe.recovery(id)',rid);assert recovery['report']['demand']['counts']['boarded']>0,recovery
 # Replan through the actual editor, without altering population or work rosters.
 p.locator('details.entry').filter(has=p.locator('[data-transit-action=edit]')).first.locator('summary').click();p.locator('[data-transit-action=edit]').first.click();p.locator('[data-transit-action=undo]').click();p.locator('[data-transit-action=undo]').click();p.locator('#transitLevel').select_option('2');p.locator('[data-transit-action=map]').click();p.evaluate('(s)=>__forecastProbe.aim(s)',recovery['spec'])
 for stop in recovery['spec']['stops']:
  point=p.evaluate('(id)=>__forecastProbe.point(id)',stop);p.mouse.click(point['x'],point['y'])
 p.locator('[data-panel=construction]').click();p.locator('[data-transit-action=quote]').click();before=p.evaluate('__forecastProbe.inspect()');p.evaluate('__townTest.step(1)');p.locator('[data-transit-action=build]').click();stale=p.evaluate('__forecastProbe.inspect()');assert stale['routes'][0]['vehicles']==1 and stale['paused'],'Stale review bought a second bus';p.locator('[data-transit-action=build]').click();p.evaluate('__townTest.step(1)');recovered=p.evaluate('__forecastProbe.inspect()');assert recovered['daily']['rides']>poor['daily']['rides'] and recovered['daily']['revenue']>0,recovered
 assert recovered['fare']==.65 and recovered['population']==start['population'] and abs(recovered['total']-start['total'])<.001,recovered
 p.locator('details.entry').filter(has=p.locator('[data-transit-action=report]')).first.locator('summary').click();p.locator('[data-transit-action=report]').first.click();texts=p.locator('.transit-demand-report').all_inner_texts();assert any('entire network' in text for text in texts),texts;p.set_viewport_size({'width':390,'height':844});p.screenshot(path=str(ROOT/'reports/transit-demand-mobile.png'));assert p.evaluate('document.documentElement.scrollWidth<=innerWidth');edge=p.evaluate('(id)=>__forecastProbe.edgeCases(id)',rid);replay=p.evaluate('(id)=>__forecastProbe.replay(id)',rid);released=p.evaluate('(id)=>__forecastProbe.release(id)',rid);assert released['populated']and released['empty']and released['unchanged'],released;assert not errors,errors;b.close()
